INSERT INTO first_aid_step (step_order,title,emoji,hint,decision_point,interaction_type,correct_answer,wrong_answer,feedback_right,feedback_wrong,pass_condition,score,sort) VALUES
(1,'脱离险境','🏃','刚被蛇咬了，首先应该做什么？','快速脱离','choice','赶紧跑开，远离毒蛇','站着不动看蛇会不会走','✓ 立刻远离蛇！安全第一！不要试图抓蛇或拍照！','❌ 毒蛇可能还在攻击范围内！必须立刻退后 3-5 米远离！','选对正确选项',10,1),
(2,'辨认蛇种','🐍','远离后怎么判断是不是毒蛇？','判断蛇种','choice','三角形头 + 明显毒牙 + 彩色花纹','圆头就是毒蛇 / 小蛇无毒大蛇有毒','✓ 好眼力！三角头是毒蛇典型标志！咬伤有2个深牙印也是毒蛇！','❌ 毒蛇特征：三角头、2个毒牙、花纹艳丽！看到就当有毒处理！','选对正确选项',10,2),
(3,'保持镇定','😌','确认是毒蛇咬伤后最重要的是？','控制情绪','choice','保持冷静，不要慌，记住蛇的特征','嚎啕大哭 / 跑回家 / 用嘴吸毒','✓ 对！紧张会加速心跳，蛇毒扩散更快！深呼吸保持镇静！','❌ 千万不要跑！也别用嘴吸！口腔有溃疡反而害你！','选对正确选项',10,3),
(4,'紧急呼救','📞','现在立刻拨打 120！','拨打急救电话','phone','依次按下 1-2-0-呼叫','只按1-2就停 / 拨110','✓ 打通后说清楚：蛇咬伤！在XX路XX地方！人还清醒！','❌ 必须拨完 1-2-0 再按呼叫键！','依次按下 1-2-0-呼叫',15,4),
(5,'伤口解压','💧','伤口怎么处理？','伤口清洗','choice','用清水或肥皂水冲洗伤口周围','酒精碘酒涂 / 刀切排毒 / 敷草药','✓ 对！用流动清水冲洗伤口周围即可，不要刺激伤口！','❌ 千万别用刀切开！别用酒精碘酒涂！只用清水轻轻冲洗！','选对正确选项',10,5),
(6,'伤肢制动','🦿','咬伤的手/腿应该怎么放？','伤肢位置','limb','放平放低（与心脏同高）','抬高 / 放很低','✓ 对！伤肢要放平放低，与心脏同高！','❌ 抬高会加速毒扩散！放太低也不行！必须与心脏同高平放！','选"平放"选项',15,6),
(7,'加压包扎','🩹','用绷带在伤口上方8-10cm处绑紧','包扎操作','drag','拖拽包扎带缠绕伤口上方','直接盖住伤口 / 绑太松','✓ 完美！包扎位置正确！松紧合适减缓淋巴回流！每1小时松15分钟！','❌ 包扎位置不对！必须在伤口上方（靠近心脏一侧）8-10cm处！','拖拽包扎带到正确位置',15,7),
(8,'止痛处理','💊','伤者痛得厉害，怎么处理？','止痛禁忌','choice','绝对不要用止痛药！会加速毒扩散','吃止痛药 / 喝白酒 / 冰敷','✓ 对！止痛药和酒精影响凝血！冰敷让血管收缩加重坏死！','❌ 绝对不能吃止痛药！不能喝酒！不能冰敷！疼就忍着！','选对正确选项',10,8),
(9,'禁忌清单','🚫','下面哪个是**允许**做的？','禁忌判断','choice','多喝水帮助代谢','吸毒 / 敷草药 / 吃鸡蛋','✓ 多喝水！帮助代谢！记住三大禁忌：不切！不吸！不敷！','❌ 吸毒/敷草药/吃大蒜都不行！只有多喝水是对的！','选对正确选项',10,9);
